let A, B;
let x, y, R;

let a = 0,
  b = 0;

let delta;

let r = 5;

function setup() {
  createCanvas(windowWidth, windowHeight);
  noStroke();

  R = max(width, height) * 0.225;
  delta = TWO_PI / (360 * r);

  background(0);
}

function draw() {
  background(0, 10);
  push();
  translate(width / 2, height);
  rotate(radians(-90));

  for (let i = 0; i < TWO_PI; i += (Math.max(0.001, Math.abs(delta)) || 1)) {
    A = cos(a * 2 + frameCount * 0.01) + tan(sin(frameCount * 0.015));
    B = (cos(a * 3 - frameCount * 0.013) - cos(a * 5)) / 5 - cos(cos(frameCount * 0.01));
    x = R * (A + 1) * sin(b + B);
    y = R * (A + 1) * cos(b + B);

    a += 1.0;
    b += 0.2;

    if (a % 10 == 0) {
      r = 5;
      fill("#E5D0A6");
    } else {
      r = 1;
      fill("#FFFFFF");
    }

    circle(x, y, r);
  }

  pop();
}
